# --- CELL 2: UNPACK PROJECT OVERRIDE MODULES ---
import os, base64, gzip, io
from pathlib import Path

payload_b64 = ""
buf = io.BytesIO(base64.b64decode(payload_b64))
with gzip.open(buf, "rb") as f:
    raw = f.read()

pos = 0
while pos < len(raw):
    rel_len = int.from_bytes(raw[pos:pos+2], "byteorder")
    pos += 2
    rel_path = raw[pos:pos+rel_len].decode("utf-8")
    pos += rel_len
    data_len = int.from_bytes(raw[pos:pos+4], "byteorder")
    pos += 4
    data = raw[pos:pos+data_len]
    pos += data_len
    
    target = Path(rel_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)

print("[OK] Unpacked all project_override modules successfully.")


# --- CELL 3: MY_AGENT IMPLEMENTATION ---
import threading
from typing import Any, List
import numpy as np

from agents.agent import Agent
from agents.structs import FrameData, GameAction, GameState
from project_override.orchestration.general_agent import GeneralAgent

_COMPUTE_SEMAPHORE = threading.Semaphore(2)


class MyAgent(Agent):
    """Competition Entrypoint for ARC-AGI-3 (Swarm / Multi-Thread Safe)."""

    def __init__(self, *args: Any, **kwargs: Any):
        super().__init__(*args, **kwargs)
        gid = getattr(self, "game_id", "arc_game")
        self.orchestration_agent = GeneralAgent(game_id=str(gid))

    def is_done(self, frames: List[FrameData], latest_frame: FrameData) -> bool:
        return latest_frame.state == GameState.WIN

    def choose_action(self, frames: List[FrameData], latest_frame: FrameData) -> GameAction:
        if latest_frame.state in (GameState.NOT_PLAYED, GameState.GAME_OVER):
            if latest_frame.state == GameState.GAME_OVER:
                self.orchestration_agent.on_game_over()
            return GameAction.RESET

        raw_frame = latest_frame.frame
        frame_seq: List[np.ndarray] = []
        if isinstance(raw_frame, list) and len(raw_frame) > 0:
            arr = np.asarray(raw_frame, dtype=np.int8)
            if arr.ndim == 3:
                frame_seq = [arr[i] for i in range(arr.shape[0])]
                grid = arr[-1]
            else:
                grid = arr
        else:
            grid = np.zeros((64, 64), dtype=np.int8)

        avail_raw = getattr(latest_frame, "available_actions", None) or [1, 2, 3, 4]
        avail_ids = [int(getattr(a, "value", a)) for a in avail_raw]
        lvls = int(getattr(latest_frame, "levels_completed", 0) or 0)

        with _COMPUTE_SEMAPHORE:
            act_id, data = self.orchestration_agent.step(
                grid=grid,
                available_actions=avail_ids,
                levels_completed=lvls,
                frame_sequence=frame_seq,
            )

        try:
            action = GameAction.from_id(int(act_id))
        except Exception:
            action = GameAction.ACTION1

        if action == GameAction.ACTION6 and data:
            action.set_data({"x": int(data.get("x", 32)), "y": int(data.get("y", 32))})

        return action



# --- CELL 4: COMPETITION RUNNER & DUAL-PHASE PARQUET HANDLER ---
import os
import subprocess
import pandas as pd

is_rerun = os.getenv("KAGGLE_IS_COMPETITION_RERUN") == "1" or os.getenv("KAGGL_IS_COMPETITION_RERUN") == "1"

if is_rerun:
    print("[RERUN] Competition evaluation mode active. Waiting for gateway...")
    subprocess.run(["curl", "--fail", "--retry", "999", "--retry-all-errors", "--retry-delay", "2", "--retry-max-time", "600", "http://gateway:8001/api/games"], check=False)
else:
    print("[PHASE-A] Save & Run All mode active. Generating mandatory sample submission.parquet for validation...")
    try:
        # Standard ARC-AGI-3 sample submission format for Phase A validation pass
        df_sub = pd.DataFrame(
            data=[["1_0", "1", True, 1.0]],
            columns=["row_id", "game_id", "end_of_game", "score"]
        )
        df_sub.to_parquet("/kaggle/working/submission.parquet", index=False)
        print("[PARQUET] Successfully wrote sample /kaggle/working/submission.parquet")
    except Exception as e:
        print(f"[PARQUET-FALLBACK] Error: {e}")
        pd.DataFrame({"status": ["ok"]}).to_parquet("/kaggle/working/submission.parquet", index=False)
        print("[PARQUET] Wrote minimal fallback submission.parquet")

print("ARC-AGI-3 Environment Setup & Parquet Handlers Initialized.")
